describe('Table Row Numbers in First Column', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should display row numbers in the first column for each table row', () => {
    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Verify table headers are present
    cy.get('[data-testid="table-header"]').should('contain', 'Row Number');
    cy.get('[data-testid="table-header"]').should('contain', 'Name');
    cy.get('[data-testid="table-header"]').should('contain', 'Email');

    // Verify table rows are present
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Verify row number is displayed in the first column
    cy.get('[data-testid="table-row"]').first().within(() => {
      cy.get('[data-testid="row-number"]').should('be.visible');
      cy.get('[data-testid="row-number"]').should('contain', '1');
    });

    // Verify row number increments with each row
    cy.get('[data-testid="table-row"]').eq(1).within(() => {
      cy.get('[data-testid="row-number"]').should('contain', '2');
    });

    cy.get('[data-testid="table-row"]').eq(2).within(() => {
      cy.get('[data-testid="row-number"]').should('contain', '3');
    });

    // Verify row number formatting (e.g., leading zeros)
    cy.get('[data-testid="table-row"]').eq(10).within(() => {
      cy.get('[data-testid="row-number"]').should('contain', '01');
    });

    // Verify row number is clickable (for row selection)
    cy.get('[data-testid="row-number"]').first().should('be.visible');
    cy.get('[data-testid="row-number"]').first().should('be.clickable');
  });

  it('should handle empty table with no rows gracefully', () => {
    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Verify table headers are present
    cy.get('[data-testid="table-header"]').should('contain', 'Row Number');
    cy.get('[data-testid="table-header"]').should('contain', 'Name');
    cy.get('[data-testid="table-header"]').should('contain', 'Email');

    // Verify no rows are present
    cy.get('[data-testid="table-row"]').should('not.exist');

    // Verify no row number is displayed
    cy.get('[data-testid="table-container"]').should('not.contain', 'Row Number');

    // Verify empty state message is displayed
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No data available');
  });
});
